// The languages the app supports, and the fixed labels for the customer pages.
// To add a language: add it to LANGUAGES, then run `npm run labels` to translate every label set into it
// (results go to labels.generated.json). English, Hindi and Kannada labels are written by hand below;
// the rest are generated by Claude from the English, with the Hindi and Kannada as style examples.
// Dish names and descriptions are not here; they come from menu_items.translations.
import generated from "./labels.generated.json";

export const LANGUAGES = [
  { code: "en", label: "English", name: "English", speech: "en-IN" },
  { code: "hi", label: "हिन्दी", name: "Hindi", speech: "hi-IN" },
  { code: "kn", label: "ಕನ್ನಡ", name: "Kannada", speech: "kn-IN" },
  { code: "ta", label: "தமிழ்", name: "Tamil", speech: "ta-IN" },
  { code: "te", label: "తెలుగు", name: "Telugu", speech: "te-IN" },
  { code: "ml", label: "മലയാളം", name: "Malayalam", speech: "ml-IN" },
  { code: "mr", label: "मराठी", name: "Marathi", speech: "mr-IN" },
  { code: "bn", label: "বাংলা", name: "Bengali", speech: "bn-IN" },
  { code: "gu", label: "ગુજરાતી", name: "Gujarati", speech: "gu-IN" },
] as const;

export type Lang = (typeof LANGUAGES)[number]["code"];

// English name of a language, for prompts: "Tamil".
export function languageName(code: Lang): string {
  return LANGUAGES.find((l) => l.code === code)?.name ?? "English";
}

// Merges a label set: English first, so a label missing in another language shows in English rather than blank.
type LabelSet<T> = Partial<Record<Lang, Partial<T>>>;
export function labelsFor<T extends object>(handWritten: LabelSet<T> & { en: T }, section: keyof typeof generated, lang: Lang): T {
  const fromClaude = (generated[section] as unknown as LabelSet<T>)[lang];
  return { ...handWritten.en, ...fromClaude, ...handWritten[lang] } as T;
}
export const DEFAULT_LANG: Lang = "en";
export const LANG_COOKIE = "lang";

export function isLang(value: unknown): value is Lang {
  return LANGUAGES.some((l) => l.code === value);
}

// The customer's own choice (saved in a cookie) wins; otherwise English.
// To follow the phone's language again, set FOLLOW_BROWSER_LANGUAGE to true: then the browser's
// Accept-Language header is used before falling back to English.
const FOLLOW_BROWSER_LANGUAGE = false;

export function pickLanguage(cookieValue: string | undefined, acceptLanguage: string | null): Lang {
  if (isLang(cookieValue)) return cookieValue;
  if (FOLLOW_BROWSER_LANGUAGE) {
    for (const part of (acceptLanguage ?? "").split(",")) {
      const code = part.split(";")[0].trim().toLowerCase().split("-")[0];
      if (isLang(code)) return code;
    }
  }
  return DEFAULT_LANG;
}

