// Exported so the label script can translate them into the other languages.
export const CUSTOMER_LABELS = { en, hi, kn };

export function getDictionary(lang: Lang): Dictionary {
  return labelsFor<Dictionary>(CUSTOMER_LABELS, "customer", lang);
}

// fill("Order by {time}", { time: "11:00 AM" }) -> "Order by 11:00 AM"
export function fill(template: string, values: Record<string, string | number>): string {
  return template.replace(/\{(\w+)\}/g, (_, key: string) => String(values[key] ?? ""));
}
